import {t} from './locales.js';import {COW} from './cow-config.js';import {cowRecoveryReason,cowAccessibleSupply} from './cow-recovery.js';
/** @param {import('./engine.js').State} state @param {import('./cow-panel.js').CowSend} send @param {HTMLElement} host */
export function renderCowRecovery(state,send,host){const g=state.cow;if(!g?.visited)return;const box=document.createElement('section'),heading=document.createElement('h3'),help=document.createElement('p'),stock=document.createElement('p'),reason=document.createElement('p'),button=document.createElement('button'),supply=cowAccessibleSupply(state),active=g.recovery.active,blocked=cowRecoveryReason(state,active);box.id='cow-care-job';heading.textContent=t('cowCareJob');help.textContent=t('cowRecoveryHelp');stock.textContent=t('cowAllUsableSupplies')+': '+supply.feedG/1000+' kg / '+supply.waterMl/1000+' L';reason.id='cow-care-job-reason';reason.textContent=blocked?t(blocked):t('cowCareJobEligible');if(active)reason.textContent+=' '+Math.max(0,COW.recoveryHours-(state.tick-g.recovery.startedTick))+' '+t('cowGameHour')+'.';button.type='button';button.id=active?'complete-cow-care-job':'start-cow-care-job';button.className='action-button';button.textContent=t(active?'cowCompleteCareJob':'cowStartCareJob');button.disabled=!!blocked;button.setAttribute('aria-describedby',reason.id);button.addEventListener('click',event=>{if(event.detail>1)return;send(active?'completeCowCareJob':'startCowCareJob');});box.append(heading,help,stock,reason,button);host.append(box);}
